OPS = {
    "+": lambda a, b: a + b,
    "-": lambda a, b: a - b,
    "*": lambda a, b: a * b,
    "=": lambda a, b: a == b,
    ">": lambda a, b: a > b,
    "AND": lambda a, b: bool(a) and bool(b),
}


class Expr:
    def __init__(self, kind, val=None, children=()):
        self.kind = kind
        self.val = val
        self.children = list(children)

    def size(self):
        return 1 + sum(c.size() for c in self.children)

    def text(self):
        if self.kind == "Lit":
            return str(self.val).lower() if isinstance(self.val, bool) else str(self.val)
        if self.kind == "Col":
            return self.val
        return "(" + self.children[0].text() + " " + self.val + " " + self.children[1].text() + ")"


def Lit(v):
    return Expr("Lit", v)


def Col(n):
    return Expr("Col", n)


def Bin(op, a, b):
    return Expr("Bin", op, [a, b])


def fold(e):
    if e.kind != "Bin":
        return e
    a = fold(e.children[0])
    b = fold(e.children[1])
    op = e.val
    # 代数恒等式：x + 0 = x, x - 0 = x, x * 1 = x, x AND true = x
    if op == "+" and b.kind == "Lit" and b.val == 0:
        return a
    if op == "-" and b.kind == "Lit" and b.val == 0:
        return a
    if op == "*" and b.kind == "Lit" and b.val == 1:
        return a
    if op == "AND" and b.kind == "Lit" and b.val is True:
        return a
    # 常量折叠：两侧都是字面量 -> 直接求值
    if a.kind == "Lit" and b.kind == "Lit":
        return Lit(OPS[op](a.val, b.val))
    return Bin(op, a, b)


e1 = Bin("*", Bin("+", Lit(1), Lit(2)), Bin("+", Col("salary"), Lit(0)))
e2 = Bin("AND", Bin(">", Col("age"), Lit(30)), Bin("=", Lit(1), Lit(1)))
e3 = Bin("=", Lit(1), Lit(0))

f1, f2, f3 = fold(e1), fold(e2), fold(e3)
for i, (a, b) in enumerate([(e1, f1), (e2, f2), (e3, f3)], 1):
    print("表达式" + str(i) + ": " + a.text() + "   节点数=" + str(a.size()))
    print("折叠后  : " + b.text() + "   节点数=" + str(b.size()))
    print("  节点数下降: " + str(b.size() < a.size()))

